import React, { CSSProperties, PropsWithChildren } from 'react';
import { ErrorBoundary } from 'react-error-boundary';
import styled from 'styled-components';

import { EmptyState } from './EmptyState.js';
import { ErrorState } from './ErrorState.js';
import { LoaderOverlay } from '../loader-overlay/LoaderOverlay.js';

const StateHandlerContainer = /* @__PURE__ */ styled('div')<{
  height: string | number;
  isLoading: boolean;
}>(({ height, isLoading }) => ({
  position: 'relative',
  height: height,
  width: '100%',
  filter: isLoading ? 'opacity(85%)' : 'none',
}));

interface ChartStateHandlerProps {
  empty: boolean;
  height: string | number;
  emptyState: React.ReactNode | undefined;
  errorState: React.ReactNode | ((message: string) => JSX.Element) | undefined;
  isLoading: boolean;
  style?: CSSProperties;
  className?: string;
}
const getContent = (props: PropsWithChildren<ChartStateHandlerProps>) => {
  const { empty, height, emptyState, errorState, children, isLoading } = props;

  if (empty) {
    return isLoading ? (
      <LoaderOverlay />
    ) : (
      <EmptyState height={height}>{emptyState}</EmptyState>
    );
  }

  return (
    <ErrorBoundary
      FallbackComponent={ErrorState({
        height: height,
        children: errorState,
      })}
    >
      {children}
      {isLoading && <LoaderOverlay />}
    </ErrorBoundary>
  );
};

export function ChartStateHandler(
  props: PropsWithChildren<ChartStateHandlerProps>,
) {
  const content = getContent(props);

  return <StateHandlerContainer {...props}>{content}</StateHandlerContainer>;
}
